(function(){'use strict';const $=id=>document.getElementById(id),D=window.AguaTwinDecision;let last=null;
const examples=[{id:'A',flow_m3_h:5,hours_day:6,tds_mg_l:5000,recovery:.5,rejection:.98,dynamic_head_m:80,pump_efficiency:.55,ro_kwh_per_m3_permeate:5,fixed_cost_brl_day:13},{id:'B',flow_m3_h:2,hours_day:6,tds_mg_l:2000,recovery:.6,rejection:.98,dynamic_head_m:50,pump_efficiency:.65,ro_kwh_per_m3_permeate:2,fixed_cost_brl_day:13},{id:'C',flow_m3_h:1.5,hours_day:6,tds_mg_l:1200,recovery:.7,rejection:.98,dynamic_head_m:40,pump_efficiency:.6,ro_kwh_per_m3_permeate:1.5,fixed_cost_brl_day:13}];
const fields=[['flow_m3_h','Vazão (m³/h)',0,1000,.1],['hours_day','Horas/dia',0,24,1],['tds_mg_l','STD (mg/L)',0,100000,50],['recovery','Recuperação (%)',1,99,1],['rejection','Rejeição de sais (%)',0,100,1],['dynamic_head_m','Altura total (m)',0,2000,1],['pump_efficiency','Eficiência da bomba (%)',1,100,1],['ro_kwh_per_m3_permeate','Osmose (kWh/m³ produzido)',.01,100,.1],['fixed_cost_brl_day','Custo fixo (R$/dia)',0,100000,1]],percent=new Set(['recovery','rejection','pump_efficiency']);
const fmt=(n,d=2)=>n===null?'—':n.toLocaleString('pt-BR',{maximumFractionDigits:d,minimumFractionDigits:d});
function renderInputs(){ $('rInputs').innerHTML='<caption>Exemplos hipotéticos; dados de campo precisam ser medidos e revisados.</caption><thead><tr><th>Entrada</th>'+examples.map(o=>`<th>Alternativa ${o.id}</th>`).join('')+'</tr></thead><tbody>'+fields.map(([key,label,min,max,step])=>`<tr><th scope="row">${label}</th>${examples.map(o=>`<td><input aria-label="${label}, alternativa ${o.id}" data-option="${o.id}" data-field="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${percent.has(key)?o[key]*100:o[key]}"></td>`).join('')}</tr>`).join('')+'</tbody>';}
function conditions(){return {available_kwh_day:$('rEnergy').valueAsNumber,energy_brl_kwh:$('rPrice').valueAsNumber,concentrate_brl_m3:$('rBrine').valueAsNumber,daily_budget_brl:$('rBudget').valueAsNumber,tds_limit_mg_l:$('rLimit').valueAsNumber,demand_m3_day:$('rDemand').valueAsNumber};}
function options(){return examples.map(o=>{const out={id:o.id};for(const [key]of fields){const input=$('rInputs').querySelector(`[data-option="${o.id}"][data-field="${key}"]`);out[key]=input.valueAsNumber/(percent.has(key)?100:1);}return out;});}
function invalidate(){last=null;$('rDownload').disabled=true;$('rError').textContent='Entradas alteradas. Compare novamente para atualizar os resultados.';$('rResults').innerHTML='<tbody><tr><td>Resultados anteriores desatualizados.</td></tr></tbody>';$('rStrategies').innerHTML='';}
function compare(){try{const inputs=options(),c=conditions(),result=D.compare(inputs,c);last={version:'2.1',created_at:new Date().toISOString(),input_origin:'User-edited scenarios; initial A/B/C are hypothetical',inputs,...result};
 $('rResults').innerHTML='<caption>Volume condicional atende apenas ao critério experimental de sais. Não equivale a água potável certificada.</caption><thead><tr><th>Alternativa</th><th>Entrada (m³/dia)</th><th>Permeado (m³/dia)</th><th>STD permeado (mg/L)</th><th>Volume condicional (m³/dia)</th><th>Concentrado (m³/dia)</th><th>Energia (kWh/dia)</th><th>Custo (R$/dia)</th><th>R$/m³ condicional</th><th>Demanda atendida</th></tr></thead><tbody>'+result.results.map(r=>`<tr><td>${r.id}${r.budget_eligible?'':' • custo fixo supera orçamento'}</td><td>${fmt(r.feed_m3)}</td><td>${fmt(r.permeate_m3)}</td><td>${fmt(r.permeate_tds_mg_l,1)}</td><td>${fmt(r.conditional_volume_m3)}</td><td>${fmt(r.concentrate_m3)}</td><td>${fmt(r.energy_kwh)}</td><td>${fmt(r.cost_brl)}</td><td>${fmt(r.cost_per_conditional_m3)}</td><td>${fmt(r.demand_coverage*100,1)}%</td></tr>`).join('')+'</tbody>';
 const labels={production:'Maior produção bruta',production_and_feed_salinity:'Produção + sais na entrada',conditional_treated_water:'Maior volume após tratamento'};
 $('rStrategies').innerHTML=Object.entries(result.strategies).map(([key,id])=>`<div class="card"><h3>${labels[key]}</h3><div class="r-choice">${id?'Alternativa '+id:'Nenhuma elegível'}</div><p class="small">${key==='conditional_treated_water'?'Atende somente ao critério experimental de sais no permeado.':key==='production'?'Prioriza vazão × horas, sob as restrições comuns.':'Exige também STD na entrada dentro do critério escolhido.'}</p></div>`).join('');$('rError').textContent='Comparação atualizada. Cenários condicionais, sujeitos a medição e validação.';$('rDownload').disabled=false;return result;
 }catch(e){last=null;$('rDownload').disabled=true;$('rError').textContent=e.message;$('rResults').innerHTML='<tbody><tr><td>Corrija as entradas para comparar.</td></tr></tbody>';$('rStrategies').innerHTML='';return null;}}
$('rCompare').addEventListener('click',compare);$('rReset').addEventListener('click',()=>{renderInputs();compare();});$('rInputs').addEventListener('input',invalidate);['rEnergy','rBudget','rPrice','rBrine','rLimit','rDemand'].forEach(id=>$(id).addEventListener('input',invalidate));
$('rNASA').addEventListener('click',()=>{try{const pv=$('rPv').valueAsNumber,pr=$('rPr').valueAsNumber/100,month=String($('rMonth').value).padStart(2,'0');if(!Number.isFinite(pv)||pv<=0||!Number.isFinite(pr)||pr<=0||pr>1)throw Error('Informe potência e fator de desempenho válidos.');const climate=window.AguaTwin.getClimate(),rows=climate.rows.filter(r=>r.date.startsWith('2025-'+month));if(!rows.length)throw Error('Mês não disponível na série ativa.');const mean=rows.reduce((s,r)=>s+r.solar,0)/rows.length,energy=pv*mean/3.6*pr;$('rEnergy').value=energy.toFixed(4);$('rNasaNote').textContent=`NASA POWER • 2025-${month} • ponto ${climate.source.latitude}°, ${climate.source.longitude}°: ${fmt(mean)} MJ/m²/dia; estimativa média ${fmt(energy)} kWh/dia. Média histórica, sem garantia de potência contínua.`;compare();}catch(e){$('rNasaNote').textContent=e.message;}});
$('rDownload').addEventListener('click',()=>{if(!last)return;const url=URL.createObjectURL(new Blob([JSON.stringify(last,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='AguaTwin_comparacao_condicional.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
window.AguaTwinRural={compare,conditions,getLast:()=>last};renderInputs();compare();})();
